use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn clip_value(x: i8, min_val: i8, max_val: i8) -> i8 {
    if min_val <= max_val {
        if x < min_val {
            min_val
        } else if x > max_val {
            max_val
        } else {
            x
        }
    } else {
        max_val
    }
}

fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> (result: Vec<i8>)
    ensures
        result.len() == arr.len(),
        forall|i: int| 0 <= i && i < arr.len() ==> 
            result[i] == clip_value(arr[i], min_val, max_val)
{
    let mut result_vec = Vec::new();
    let mut i: usize = 0;
    
    while i < arr.len()
        invariant
            0 <= i <= arr.len(),
            result_vec.len() == i,
            forall|j: int| 0 <= j && j < i ==>
                result_vec[j] == clip_value(arr[j], min_val, max_val),
    {
        let clipped_val = clip_value(arr[i], min_val, max_val);
        result_vec.push(clipped_val);
        i = i + 1;
    }
    
    result_vec
}

}
